import React from 'react';
import { graphql, useStaticQuery} from 'gatsby';
import { Helmet } from 'react-helmet';
import { useLocation } from '@reach/router';



export default function SEO({ title, description, image, post }) {
  const data = useStaticQuery(graphql`
    {
      site {
        siteMetadata {
          siteUrl
          title
          description
          image
          author
        }
      }
    }
  `);

  const defaults = data.site.siteMetadata;
  const { pathname } = useLocation();

  const structuredData = post ? (
    <script type="application/ld+json">
      {JSON.stringify({
        '@context': 'https://schema.org',
        '@type': 'BlogPosting',
        headline: post.BlogTitle,
        description: post.BlogExcerpt,
        author: {
          '@type': 'Person',
          name: defaults.author,
        },
        datePublished: post.BlogDate,
        image:post.BlogFeaturedImage[0].thumbnails.large.url,
      })}
    </script>
  ) : null;

  const seo = {
    title: title || defaults.title,
    description: description || defaults.description,
    image: image ? `${image}` : defaults.image,
    url : defaults.siteUrl + pathname,
    type: post ?'article':'website'
  };

  return (
    <Helmet title={seo.title}>
      <html lang="en" />
      <meta name="description" content={seo.description} />
      <meta name="image" content={seo.image} />
      <meta property="og:type" content={seo.type} />
      <meta property="og:title" content={seo.title} />
      <meta property="og:description" content={seo.description} />
      <meta property="og:url" content={seo.url} />
      <meta property="og:image" content={seo.image} />
      <meta name="twitter:card" content="summary" />
      <meta name="twitter:title" content={seo.title} />
      <meta name="twitter:description" content={seo.description} />
      <meta name="twitter:url" content={seo.url} />
      {structuredData}
    </Helmet>
  );
}